package com.wildboy;
import static com.wildboy.Models.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.time.OffsetDateTime;
import java.util.*;
import java.util.concurrent.*;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc
class WaitlistNotificationIntegrationTest {
 static final EmbeddedPostgres pg;static{try{pg=EmbeddedPostgres.builder().setServerConfig("unix_socket_directories", "").start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->pg.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"");r.add("wildboy.notifications.scan-ms",()->"3600000");}
 @DynamicPropertySource static void identityProperties(DynamicPropertyRegistry r){r.add("wildboy.identity.encryption-key",()->Base64.getEncoder().encodeToString(new byte[32]));}
 @Autowired WaitlistService waitlists;@Autowired ActivityService activities;@Autowired LegalService legal;@Autowired AuthService auth;@Autowired JdbcTemplate db;@Autowired NotificationService notifications;@Autowired MockMvc mvc;
 @MockitoBean WechatNotificationGateway gateway;
 @BeforeEach void setup(){db.update("DELETE FROM notification_outbox");db.update("DELETE FROM notification_permission");db.update("DELETE FROM activity_waitlist");db.update("DELETE FROM registration_participant");db.update("DELETE FROM registration");db.update("DELETE FROM activity");db.execute("TRUNCATE legal_consent,legal_document_version");db.update("UPDATE legal_document_state SET draft_title='',draft_content='',draft_revision=0,published_version=NULL");for(var kind:LegalModels.Kind.values()){var d=legal.save(kind,new LegalModels.DraftInput("Test "+kind,"Test synthetic policy for QA only.",0L),"test");legal.publish(kind,d.draft().revision(),"test");}reset(gateway);when(gateway.ready()).thenReturn(false);}
 User user(){return auth.user("wechat:qa-"+UUID.randomUUID(),"QA","USER");}
 Activity activity(int cap){var s=OffsetDateTime.now().plusDays(2);var a=activities.create(new ActivityInput("QA hike",Category.WEEKLY,"/assets/hiking.jpg",List.of(),"Summary","Details","Xiamen","Gate",s,s.plusHours(2),s.minusHours(1),cap,0,null,false),"test");return activities.publish(a.id(),a.version(),"test");}
 RegistrationInput input(int count){var p=new ArrayList<ParticipantInput>();for(int i=0;i<count;i++)p.add(new ParticipantInput("QA "+i,"","13800000000"));return new RegistrationInput(p,1L,1L);}
 @Test void fifoGroupsReserveAndExpireWithoutSplitting(){var a=activity(3);var owner=user();activities.register(a.id(),owner.id(),input(3));var first=user();var second=user();var e=waitlists.join(a.id(),first.id(),input(2));var f=waitlists.join(a.id(),second.id(),input(2));assertThat(e.status()).isEqualTo("WAITING");activities.cancelOwn(a.id(),owner.id());assertThat(waitlists.entry(e.id(),first.id()).status()).isEqualTo("OFFERED");assertThat(waitlists.entry(f.id(),second.id()).status()).isEqualTo("WAITING");assertThatThrownBy(()->activities.register(a.id(),user().id(),input(1))).isInstanceOf(ApiException.class);db.update("UPDATE activity_waitlist SET offer_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE id=?",e.id());waitlists.promote(a.id());assertThat(waitlists.entry(e.id(),first.id()).status()).isEqualTo("EXPIRED");assertThat(waitlists.entry(f.id(),second.id()).status()).isEqualTo("OFFERED");var r=waitlists.confirm(f.id(),second.id(),new LegalModels.ConsentInput(1L,1L));assertThat(r.participants()).hasSize(2);assertThat(waitlists.confirm(f.id(),second.id(),new LegalModels.ConsentInput(1L,1L)).id()).isEqualTo(r.id());assertThat(activities.get(a.id(),true).registeredCount()).isEqualTo(2);assertThat(db.queryForObject("SELECT participants_json FROM activity_waitlist WHERE id=?",String.class,f.id())).isEqualTo("[]");}
 @Test void insufficientSeatsDoNotSkipFirstGroupAndCancelledActivityClosesQueue(){var a=activity(3);var owner=user();activities.register(a.id(),owner.id(),input(2));var first=user();var second=user();waitlists.join(a.id(),first.id(),input(2));var e=waitlists.join(a.id(),second.id(),input(1));waitlists.promote(a.id());assertThat(waitlists.entry(e.id(),second.id()).status()).isEqualTo("WAITING");var latest=activities.get(a.id(),true);activities.cancel(a.id(),latest.version(),"test");assertThat(waitlists.entry(e.id(),second.id()).status()).isEqualTo("CANCELLED");}
 @Test void ownershipAndAnonymousEndpoints()throws Exception{var a=activity(1);activities.register(a.id(),user().id(),input(1));var owner=user();var e=waitlists.join(a.id(),owner.id(),input(1));var other=user();assertThatThrownBy(()->waitlists.cancel(e.id(),other.id())).isInstanceOf(ApiException.class);mvc.perform(get("/api/v1/me/waitlist")).andExpect(status().isUnauthorized());mvc.perform(get("/api/v1/admin/waitlist").header("Authorization","Bearer "+auth.login(other).token())).andExpect(status().isForbidden());assertThat(waitlists.mine(other.id(),0,20).items()).isEmpty();}
 @Test void concurrentConfirmationCreatesOneRegistration()throws Exception{var a=activity(1);var holder=user();activities.register(a.id(),holder.id(),input(1));var owner=user();var e=waitlists.join(a.id(),owner.id(),input(1));activities.cancelOwn(a.id(),holder.id());try(var pool=Executors.newFixedThreadPool(4)){var jobs=new ArrayList<Callable<String>>();for(int i=0;i<4;i++)jobs.add(()->waitlists.confirm(e.id(),owner.id(),new LegalModels.ConsentInput(1L,1L)).id());var ids=new HashSet<String>();for(var result:pool.invokeAll(jobs))ids.add(result.get());assertThat(ids).hasSize(1);}assertThat(activities.get(a.id(),true).registeredCount()).isEqualTo(1);}
 @Test void notificationConfigPermissionOutcomesAndRetries(){var a=activity(1);var owner=user();activities.register(a.id(),owner.id(),input(1));notifications.enqueue(owner.id(),a,"PRETRIP","test-notice","准备出发",a.startAt());String id=notifications.list(owner.id(),0,20).items().getFirst().id();notifications.dispatch(id);assertThat(notifications.list(owner.id(),0,20).items().getFirst().status()).isEqualTo("UNCONFIGURED");when(gateway.ready()).thenReturn(true);notifications.retry(id,"admin");notifications.dispatch(id);assertThat(notifications.list(owner.id(),0,20).items().getFirst().status()).isEqualTo("NO_PERMISSION");notifications.subscribe(owner.id(),true);notifications.retry(id,"admin");when(gateway.send(anyString(),anyString(),anyString(),anyString(),any())).thenReturn(new WechatNotificationGateway.Result("SENT","",false));notifications.dispatch(id);notifications.dispatch(id);verify(gateway,times(1)).send(anyString(),anyString(),anyString(),anyString(),any());assertThat(notifications.list(owner.id(),0,20).items().getFirst().status()).isEqualTo("SENT");assertThatThrownBy(()->notifications.retry(id,"admin")).isInstanceOf(ApiException.class);}
 @Test void uncertainSendIsNotRetriedAndPretripDeduplicates(){var a=activity(1);var owner=user();activities.register(a.id(),owner.id(),input(1));when(gateway.ready()).thenReturn(true);notifications.subscribe(owner.id(),true);notifications.activityNotice(a,"PRETRIP","准备出发");notifications.activityNotice(activities.get(a.id(),true),"PRETRIP","准备出发");assertThat(notifications.list(owner.id(),0,20).items()).hasSize(1);String id=notifications.list(owner.id(),0,20).items().getFirst().id();when(gateway.send(anyString(),anyString(),anyString(),anyString(),any())).thenReturn(new WechatNotificationGateway.Result("UNKNOWN","结果未确认",false));notifications.dispatch(id);notifications.scan();verify(gateway,times(1)).send(anyString(),anyString(),anyString(),anyString(),any());assertThatThrownBy(()->notifications.retry(id,"admin")).isInstanceOf(ApiException.class);}
 @Test void staleOfferAndRescheduledPretripNeverSend(){var a=activity(1);var holder=user();activities.register(a.id(),holder.id(),input(1));var owner=user();var e=waitlists.join(a.id(),owner.id(),input(1));activities.cancelOwn(a.id(),holder.id());when(gateway.ready()).thenReturn(true);notifications.subscribe(owner.id(),true);db.update("UPDATE activity_waitlist SET offer_expires_at=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE id=?",e.id());notifications.scan();assertThat(notifications.list(owner.id(),0,20).items().getFirst().status()).isEqualTo("OBSOLETE");waitlists.promote(a.id());activities.register(a.id(),holder.id(),input(1));notifications.activityNotice(activities.get(a.id(),true),"PRETRIP","准备出发");db.update("UPDATE activity SET start_at=start_at+INTERVAL '1 day',end_at=end_at+INTERVAL '1 day' WHERE id=?",a.id());notifications.scan();assertThat(notifications.list(holder.id(),0,20).items().getFirst().status()).isEqualTo("OBSOLETE");verify(gateway,never()).send(anyString(),anyString(),anyString(),anyString(),any());}
 @Test void capacityCannotRemoveReservedWholeGroup(){var a=activity(2);var holder=user();activities.register(a.id(),holder.id(),input(2));waitlists.join(a.id(),user().id(),input(2));activities.cancelOwn(a.id(),holder.id());var x=activities.get(a.id(),true);var edit=new ActivityInput(x.title(),x.category(),x.coverUrl(),x.galleryUrls(),x.summary(),x.description(),x.location(),x.meetingPoint(),x.startAt(),x.endAt(),x.registrationDeadline(),1,0,x.version(),false);assertThatThrownBy(()->activities.edit(x.id(),edit,"test")).isInstanceOf(ApiException.class);assertThat(waitlists.reserved(x.id())).isEqualTo(2);}
 @Test void capacityCannotStrandWaitingHead(){var a=activity(10);activities.register(a.id(),user().id(),input(3));waitlists.join(a.id(),user().id(),input(8));var x=activities.get(a.id(),true);var edit=new ActivityInput(x.title(),x.category(),x.coverUrl(),x.galleryUrls(),x.summary(),x.description(),x.location(),x.meetingPoint(),x.startAt(),x.endAt(),x.registrationDeadline(),5,0,x.version(),false);assertThatThrownBy(()->activities.edit(x.id(),edit,"test")).isInstanceOf(ApiException.class);}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(booleans={false,true})
 void identityRequirementCannotStrandWaitingOrOfferedParticipants(boolean required){
   var a=activity(1);
   if(required) a=activities.edit(a.id(),new ActivityInput(a.title(),a.category(),a.coverUrl(),a.galleryUrls(),a.summary(),a.description(),a.location(),a.meetingPoint(),a.startAt(),a.endAt(),a.registrationDeadline(),a.capacity(),0,a.version(),true),"test");
   var people=required?new RegistrationInput(List.of(new ParticipantInput("QA identity","11010519491231002X","13800000000")),1L,1L):input(1);
   var holder=user();activities.register(a.id(),holder.id(),people);
   var owner=user();var e=waitlists.join(a.id(),owner.id(),people);
   for(String expected:List.of("WAITING","OFFERED")) {
     var x=activities.get(a.id(),true);
     var edit=new ActivityInput(x.title(),x.category(),x.coverUrl(),x.galleryUrls(),x.summary(),x.description(),x.location(),x.meetingPoint(),x.startAt(),x.endAt(),x.registrationDeadline(),x.capacity(),0,x.version(),!required);
     assertThat(waitlists.entry(e.id(),owner.id()).status()).isEqualTo(expected);
     assertThatThrownBy(()->activities.edit(x.id(),edit,"test")).isInstanceOf(ApiException.class).hasMessageContaining("候补");
     assertThat(activities.get(x.id(),true).identityRequired()).isEqualTo(required);
     if(expected.equals("WAITING")) activities.cancelOwn(a.id(),holder.id());
   }
   // The original queued data remains usable after the refused configuration change.
   assertThat(waitlists.confirm(e.id(),owner.id(),new LegalModels.ConsentInput(1L,1L)).participants()).hasSize(1);
 }
}
